        Button batch=new Button(this);styleButton(batch);batch.setText("应用当前边框到多张照片");batch.setAllCaps(false);panel.addView(batch);final androidx.appcompat.app.AlertDialog exportDialog=new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("导出作品").setView(panel).setPositiveButton("保存到相册",(dialog,which)->{selectExportQuality(quality.getSelectedItemPosition());export(false);}).setNeutralButton("分享作品",(dialog,which)->{selectExportQuality(quality.getSelectedItemPosition());export(true);}).setNegativeButton("取消",null).create();batch.setOnClickListener(v->{exportDialog.dismiss();configureBatch();});exportDialog.show();
