    private void configureBatch(){if(photo==null||exporting||previewPending)return;if(PhotoFrame.requiredPhotos(options.style)>1){Toast.makeText(this,"批量套框先支持单图模板，请切换边框",Toast.LENGTH_LONG).show();return;}if(FrameBatch.busy()){Toast.makeText(this,"请先完成或取消当前批量任务",Toast.LENGTH_LONG).show();return;}if(android.os.Build.VERSION.SDK_INT<29&&androidx.core.content.ContextCompat.checkSelfPermission(this,android.Manifest.permission.WRITE_EXTERNAL_STORAGE)!=android.content.pm.PackageManager.PERMISSION_GRANTED){androidx.core.app.ActivityCompat.requestPermissions(this,new String[]{android.Manifest.permission.WRITE_EXTERNAL_STORAGE},42);Toast.makeText(this,"允许保存权限后，请再次选择批量套框",Toast.LENGTH_LONG).show();return;}
        LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(20),0,dp(20),0);panel.addView(label("最多 30 张 · 每张使用自己的 EXIF",13));Spinner quality=new Spinner(this);quality.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1080px · 轻巧","2048px · 标准","4096px · 高清"}));quality.setSelection(exportPreset);panel.addView(quality);Spinner titles=new Spinner(this);titles.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"各模板默认标题","统一使用当前标题","使用各照片文件名"}));panel.addView(titles);androidx.appcompat.widget.SwitchCompat film=new androidx.appcompat.widget.SwitchCompat(this);film.setText("统一使用当前手动配方备注");film.setChecked(false);panel.addView(film);panel.addView(label("署名和边框参数统一应用；配方备注默认不复制。选择照片后可预览，再开始保存。",12));new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("批量套框设置").setView(panel).setPositiveButton("选择照片",(dialog,which)->{batchOptions=options.copy();if(!film.isChecked())batchOptions.filmNote="";batchQuality=quality.getSelectedItemPosition();batchTitlePolicy=titles.getSelectedItemPosition();try{startActivityForResult(PhotoPicker.create(this,30),604);}catch(Exception error){Toast.makeText(this,"系统相册不可用",Toast.LENGTH_LONG).show();}}).setNegativeButton("取消",null).show();}
    private void selectExportQuality(int value){exportPreset=Math.max(0,Math.min(2,value));getSharedPreferences("frame_studio",0).edit().putInt("export_preset",exportPreset).apply();scheduleDraft();}
    private void makeTemplatePreviews(){if(thumbnailPhoto==null||closed)return;final Bitmap sourcePhoto=thumbnailPhoto;final PhotoDetails metadata=details;
        for(int i:visibleStyles){ImageView target=(ImageView)templateCards[i].getChildAt(0);Bitmap cached=templateCache.get(i);if(cached!=null){target.setImageBitmap(cached);continue;}if(thumbnailRequested[i])continue;thumbnailRequested[i]=true;final int style=i;
            thumbnails.execute(()->{if(closed||!visibleStyle(style)){runOnUiThread(()->thumbnailRequested[style]=false);return;}Bitmap rendered=null;try{PhotoFrame.Options preset=new PhotoFrame.Options();preset.style=style;preset.paper=PhotoFrame.defaultPaper(style);rendered=PhotoFrame.render(sourcePhoto,metadata,preset);int edge=Math.max(rendered.getWidth(),rendered.getHeight());if(edge>256){float ratio=256f/edge;Bitmap sized=Bitmap.createScaledBitmap(rendered,Math.max(1,Math.round(rendered.getWidth()*ratio)),Math.max(1,Math.round(rendered.getHeight()*ratio)),true);if(sized!=rendered)rendered.recycle();rendered=sized;}rendered.prepareToDraw();}catch(Exception|OutOfMemoryError error){android.util.Log.w("frame-preview","Thumbnail unavailable",error);}final Bitmap result=rendered;
                runOnUiThread(()->{thumbnailRequested[style]=false;if(closed){if(result!=null)result.recycle();return;}if(result!=null){templateCache.put(style,result);if(visibleStyle(style))((ImageView)templateCards[style].getChildAt(0)).setImageBitmap(result);}});
            });
        }
    }
    @Override protected void onSaveInstanceState(Bundle state){try{if(batchOptions!=null){state.putString("batch_options",FrameDrafts.snapshot("batch-settings","","",batchOptions,java.util.Collections.emptyList(),batchQuality).toString());state.putInt("batch_title_policy",batchTitlePolicy);}state.putString("draft",draftSnapshot().toString());}catch(Exception ignored){}state.putString("title",options.title);state.putString("film_note",options.filmNote);java.util.ArrayList<String> saved=new java.util.ArrayList<>();for(Uri uri:extraUris)saved.add(uri.toString());state.putStringArrayList("collage_photos",saved);super.onSaveInstanceState(state);}
    private static int templateCategory(int style){return PhotoFrame.category(style);}
    private boolean visibleStyle(int style){for(int id:visibleStyles)if(id==style)return true;return false;}
    private void updateFavorite(){favorite.setText(collections.contains(options.style)?"★ 已收藏":"☆ 收藏边框");favorite.setContentDescription((collections.contains(options.style)?"取消收藏 ":"收藏 ")+PhotoFrame.NAMES[options.style]);}
    private void showCategory(LinearLayout row,HorizontalScrollView scroll,LinearLayout chips,int category){activeCategory=category;visibleStyles=category>=0?PhotoFrame.GROUPS[category]:collections.list(category==-1);for(int i=0;i<row.getChildCount();i++){View card=templateCards[i];card.setVisibility(visibleStyle(i)?View.VISIBLE:View.GONE);if(!visibleStyle(i))((ImageView)((LinearLayout)card).getChildAt(0)).setImageDrawable(null);}for(int id:visibleStyles)row.bringChildToFront(templateCards[id]);int selectedChip=category>=0?category:category==-1?8:9;for(int i=0;i<chips.getChildCount();i++){chips.getChildAt(i).setBackground(background(i==selectedChip?0xff555c60:0xff33373b,10));((Button)chips.getChildAt(i)).setTextColor(i==selectedChip?0xffffffff:0xffa3a8ac);}scroll.post(()->{View selected=templateCards[options.style];scroll.scrollTo(visibleStyle(options.style)?Math.max(0,selected.getLeft()-dp(8)):0,0);});View parent=(View)chips.getParent();parent.post(()->((HorizontalScrollView)parent).smoothScrollTo(Math.max(0,chips.getChildAt(selectedChip).getLeft()-dp(16)),0));if(collectionEmpty!=null){collectionEmpty.setVisibility(visibleStyles.length==0?View.VISIBLE:View.GONE);collectionEmpty.setText(category==-1?"还没有收藏，可点击上方 ☆ 收藏当前边框。":"尚无最近使用的边框。");}updateFavorite();makeTemplatePreviews();}

    private interface EffectValue{void set(int value);}
    private void addEffectControl(LinearLayout content,String caption,int max,int current,EffectValue action){TextView text=label(caption+" · "+current+"（光影系列）",12);content.addView(text);SeekBar slider=new SeekBar(this);slider.setMax(max);slider.setProgress(current);content.addView(slider);editors.add(slider);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar view){}public void onStopTrackingTouch(SeekBar view){render();}public void onProgressChanged(SeekBar view,int value,boolean user){if(caption.equals("背景虚化")&&value==0){view.setProgress(1);return;}action.set(value);text.setText(caption+" · "+value+"（光影系列）");}});}
    private void enable(boolean value){save.setEnabled(value&&!loadingExtras&&!previewPending);for(View editor:editors)editorEnabled(editor,!exporting);}
    private void render(){if(photo==null||exporting||closed)return;updateFavorite();scheduleDraft();getSharedPreferences("frame_studio",0).edit().putBoolean("light_frames_seen",true).putInt("style",options.style).putInt("paper",options.paper).putInt("spacing",options.spacing).putBoolean("sidebar_right",options.sidebarRight).putInt("blur",options.blur).putInt("corners",options.corners).putInt("shadow",options.shadow).putBoolean("parameters",options.parameters).putString("author",options.author).apply();updateCollageButton();final int generation=++renderGeneration;final PhotoFrame.Options snapshot=options.copy();final Bitmap input=small;final PhotoDetails metadata=details;final java.util.ArrayList<Bitmap> extras=new java.util.ArrayList<>(extraPreviews);previewPending=true;save.setEnabled(false);
        renders.latest(()->{if(closed||generation!=renderGeneration)return;long started=android.os.SystemClock.elapsedRealtime();Bitmap output=null;String error=null;try{output=PhotoFrame.render(input,metadata,snapshot,extras);output.prepareToDraw();}catch(Exception|OutOfMemoryError failure){error="无法生成边框，请减小边距或重试";android.util.Log.w("frame-preview","Render failed",failure);}final Bitmap result=output;final String problem=error;
            runOnUiThread(()->{if(closed||generation!=renderGeneration){if(result!=null)result.recycle();return;}previewPending=false;if(problem==null){Bitmap old=framed;framed=result;preview.setImageBitmap(framed);if(lastUsedStyle!=snapshot.style){collections.used(snapshot.style);lastUsedStyle=snapshot.style;if(activeCategory==-2)showCategory(templateRow,templatesScroll,categoryChips,-2);}if(old!=null)old.recycle();enable(true);}else{if(result!=null)result.recycle();enable(false);Toast.makeText(this,problem,Toast.LENGTH_LONG).show();}android.util.Log.i("frame-performance","Preview style "+snapshot.style+" rendered off main thread in "+(android.os.SystemClock.elapsedRealtime()-started)+" ms");});
        });
    }

    private void export(boolean sharing){if(framed==null||exporting||loadingExtras||previewPending)return;
        if(!sharing && android.os.Build.VERSION.SDK_INT<29 && androidx.core.content.ContextCompat.checkSelfPermission(this,android.Manifest.permission.WRITE_EXTERNAL_STORAGE)!=android.content.pm.PackageManager.PERMISSION_GRANTED){androidx.core.app.ActivityCompat.requestPermissions(this,new String[]{android.Manifest.permission.WRITE_EXTERNAL_STORAGE},42);Toast.makeText(this,"允许保存权限后，请再次点击保存",Toast.LENGTH_LONG).show();return;}exporting=true;enable(false);final PhotoFrame.Options snapshot=options.copy();final int edge=PhotoFrame.requiredPhotos(snapshot.style)>1?Math.min(2048,new int[]{1080,2048,4096}[exportPreset]):new int[]{1080,2048,4096}[exportPreset];final java.util.ArrayList<Uri> selectedUris=new java.util.ArrayList<>(extraUris);final int jpegQuality=exportPreset==0?85:95;
        Frontend.print("边框导出：照片最长边上限 "+edge+"px，JPEG "+jpegQuality+"%");
        new Thread(()->{File file=null;Uri uri=null;String error=null;Bitmap image=null,exportPhoto=null;java.util.ArrayList<Bitmap> extraImages=new java.util.ArrayList<>();try{exportPhoto=LocalMedia.decode(this,source,edge);if(exportPhoto==null)throw new IOException("无法读取原图");if(Math.max(exportPhoto.getWidth(),exportPhoto.getHeight())>edge){float factor=(float)edge/Math.max(exportPhoto.getWidth(),exportPhoto.getHeight());Bitmap scaled=Bitmap.createScaledBitmap(exportPhoto,Math.max(1,Math.round(exportPhoto.getWidth()*factor)),Math.max(1,Math.round(exportPhoto.getHeight()*factor)),true);if(scaled!=exportPhoto)exportPhoto.recycle();exportPhoto=scaled;}for(int i=0;i<PhotoFrame.requiredPhotos(snapshot.style)-1;i++){Bitmap extra=decodeBounded(selectedUris.get(i),edge);if(extra==null)throw new IOException("拼图照片不可读取");extraImages.add(extra);}image=PhotoFrame.render(exportPhoto,details,snapshot,extraImages);
            File folder=sharing?new File(getCacheDir(),"frames"):new File(PhotoStorage.stagingRoot(this,false),"fudge");if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("无法创建保存目录");
            if(sharing){File[] old=folder.listFiles();if(old!=null)for(File cached:old)if(cached.getName().startsWith("Fuji-frame-") && System.currentTimeMillis()-cached.lastModified()>7L*24*60*60*1000)cached.delete();}
            file=new File(folder,"Fuji-frame-"+java.util.UUID.randomUUID()+".jpg");try(OutputStream out=new FileOutputStream(file)){if(!image.compress(Bitmap.CompressFormat.JPEG,jpegQuality,out))throw new IOException("图片编码失败");}
            if(sharing)uri=Uri.fromFile(file);else{String target=PhotoStorage.publish(this,file.getAbsolutePath(),false);uri=target.startsWith("content:")?Uri.parse(target):Uri.fromFile(new File(target));if(android.os.Build.VERSION.SDK_INT>=29)file.delete();}
        }catch(Exception|OutOfMemoryError e){error="导出失败，请检查存储空间，或选择较低的导出画质";if(file!=null)file.delete();}finally{if(image!=null)image.recycle();if(exportPhoto!=null)exportPhoto.recycle();for(Bitmap extra:extraImages)extra.recycle();}
        Frontend.print(error==null?"边框副本导出成功":"边框副本导出失败");
        final Uri result=uri;final String message=error;runOnUiThread(()->{exporting=false;if(closed)return;enable(true);if(message!=null)Toast.makeText(this,message,Toast.LENGTH_LONG).show();else if(sharing)LocalMedia.share(this,result,"Fuji-frame.jpg","分享边框作品");else Toast.makeText(this,"边框副本已保存到手机相册",Toast.LENGTH_LONG).show();});},"photo-frame-export").start();
    }
    private Bitmap decodeBounded(Uri uri,int edge)throws IOException{Bitmap image=LocalMedia.decode(this,uri,edge);if(image==null)return null;int largest=Math.max(image.getWidth(),image.getHeight());if(largest<=edge)return image;try{float scale=(float)edge/largest;Bitmap scaled=Bitmap.createScaledBitmap(image,Math.max(1,Math.round(image.getWidth()*scale)),Math.max(1,Math.round(image.getHeight()*scale)),true);if(scaled!=image)image.recycle();return scaled;}catch(OutOfMemoryError error){image.recycle();throw error;}}
    private void updateCollageButton(){if(collagePhotos==null)return;int count=PhotoFrame.requiredPhotos(options.style);collagePhotos.setVisibility(count>1?View.VISIBLE:View.GONE);collagePhotos.setText(loadingExtras?"正在读取照片…":"选择拼图照片 · "+Math.min(count,1+extraUris.size())+" / "+count+" 张");collagePhotos.setEnabled(!exporting&&!loadingExtras);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==605&&result==RESULT_OK&&data!=null){filmNoteInput.setText(data.getStringExtra("film_note"));return;}if(request==604&&result==RESULT_OK&&data!=null){java.util.ArrayList<Uri> uris=new java.util.ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++){Uri u=data.getClipData().getItemAt(i).getUri();if(u!=null&&!uris.contains(u))uris.add(u);}else if(data.getData()!=null)uris.add(data.getData());if(uris.isEmpty())return;if(uris.size()>30){Toast.makeText(this,"一次最多选择 30 张照片",Toast.LENGTH_LONG).show();return;}for(Uri u:uris)try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}try{org.json.JSONObject record=FrameBatch.create(uris,batchOptions==null?options.copy():batchOptions,batchQuality,batchTitlePolicy);android.content.Context app=getApplicationContext();FrameBatch.WORK.execute(()->{try{FrameBatch task=FrameBatch.open(app,record);task.prepareNames();task.persist();runOnUiThread(()->{if(!closed)startActivity(new Intent(this,FrameBatchActivity.class).putExtra("batch",record.toString()));});}catch(Exception error){runOnUiThread(()->{if(!closed)Toast.makeText(this,"无法保存批量任务，请检查空间",Toast.LENGTH_LONG).show();});}});}catch(Exception error){Toast.makeText(this,"无法创建批量任务",Toast.LENGTH_LONG).show();}return;}if(request==603&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri replacement=data.getData();try{getContentResolver().takePersistableUriPermission(replacement,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}try{org.json.JSONObject r=draftSnapshot();r.put("source",replacement.toString());FrameDrafts.open(this,r);finish();}catch(Exception error){Toast.makeText(this,"无法重新选择原图",Toast.LENGTH_LONG).show();}return;}if(request!=602||result!=RESULT_OK||data==null)return;
        java.util.ArrayList<Uri> picked=new java.util.ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount()&&picked.size()<5;i++){Uri uri=data.getClipData().getItemAt(i).getUri();if(uri!=null&&!picked.contains(uri)&&!uri.equals(source))picked.add(uri);}}else if(data.getData()!=null&&!data.getData().equals(source))picked.add(data.getData());
        if(picked.isEmpty()){Toast.makeText(this,"请选择主照片以外的照片",Toast.LENGTH_SHORT).show();return;}
        for(Uri uri:picked)try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}
        loadExtraPhotos(picked);
    }
    private void loadExtraPhotos(java.util.ArrayList<Uri> uris){int generation=++photoLoadGeneration;loadingExtras=true;save.setEnabled(false);updateCollageButton();
        new Thread(()->{java.util.ArrayList<Bitmap> bitmaps=new java.util.ArrayList<>();String error=null;try{for(Uri uri:uris){Bitmap image=decodeBounded(uri,800);if(image==null)throw new IOException("照片无法读取");bitmaps.add(image);}}catch(Exception|OutOfMemoryError e){error="拼图照片读取失败，请重新选择";}final String problem=error;
            runOnUiThread(()->{if(closed||generation!=photoLoadGeneration){for(Bitmap image:bitmaps)image.recycle();return;}loadingExtras=false;if(problem==null){java.util.ArrayList<Bitmap> oldImages=new java.util.ArrayList<>(extraPreviews);renders.execute(()->{for(Bitmap old:oldImages)old.recycle();});extraPreviews.clear();extraPreviews.addAll(bitmaps);extraUris.clear();extraUris.addAll(uris);}else{for(Bitmap image:bitmaps)image.recycle();Toast.makeText(this,problem,Toast.LENGTH_LONG).show();}render();updateCollageButton();});
        },"collage-photo-loader").start();
    }
    @Override public boolean onOptionsItemSelected(MenuItem item){if(item.getItemId()==android.R.id.home){finish();return true;}return super.onOptionsItemSelected(item);}
    private org.json.JSONObject draftSnapshot()throws org.json.JSONException{return FrameDrafts.snapshot(draftId,source.toString(),name,options.copy(),new java.util.ArrayList<>(extraUris),exportPreset);}
    private void scheduleDraft(){if(!draftReady||closed)return;draftStatus.setText("草稿待保存…");handler.removeCallbacks(saveDraftLater);handler.postDelayed(saveDraftLater,800);}
    private void saveDraft(){if(!draftReady||source==null||draftWorker.isShutdown())return;handler.removeCallbacks(saveDraftLater);final int generation=++draftGeneration;try{final org.json.JSONObject snapshot=draftSnapshot();draftWorker.execute(()->{boolean success=true;try{new FrameDrafts(getApplicationContext()).save(snapshot);}catch(Exception error){success=false;android.util.Log.w("frame-draft","Save failed",error);}final boolean saved=success;runOnUiThread(()->{if(!closed&&generation==draftGeneration)draftStatus.setText(saved?"草稿已保存 · 可从首页继续创作":"草稿保存失败 · 点此重试");});});}catch(Exception error){draftStatus.setText("草稿保存失败 · 点此重试");}}
    private void replaceDraftPhoto(){try{startActivityForResult(PhotoPicker.create(this,1),603);}catch(Exception error){Toast.makeText(this,"系统相册不可用",Toast.LENGTH_LONG).show();}}
    @Override protected void onPause(){super.onPause();saveDraft();}
    @Override protected void onDestroy(){handler.removeCallbacks(saveDraftLater);draftWorker.shutdown();closed=true;renderGeneration++;handler.removeCallbacks(refresh);if(templateRow!=null)for(int i=0;i<templateRow.getChildCount();i++)((ImageView)templateCards[i].getChildAt(0)).setImageDrawable(null);templateCache.evictAll();if(preview!=null)preview.setImageDrawable(null);if(framed!=null)framed.recycle();if(backdrop!=null)backdrop.setImageDrawable(null);if(ambient!=null)ambient.recycle();final Bitmap original=small,tiny=thumbnailPhoto;final java.util.ArrayList<Bitmap> extras=new java.util.ArrayList<>(extraPreviews);renders.finish(()->{if(original!=null)original.recycle();for(Bitmap image:extras)image.recycle();});thumbnails.finish(()->{if(tiny!=null)tiny.recycle();});super.onDestroy();}
